const PILAR_3_ID = "3ccb979ea76f0de678f0c6d033c4cf56ae093264d575897fc742c0ccf446b8ed@group.calendar.google.com";

// ✅ Disponibilidad
const p1Disp = !tieneConflicto(solicitudFecha, inicioReal, finReal, pilar1Ocupados);
