const p3Disp = !tieneConflicto(solicitudFecha, inicioReal, finReal, pilar3Ocupados); // ← NUEVO

let calendarId = null;

// Prioridad secuencial
if (p1Disp) {
  calendarId = PILAR_1_ID;
} else if (p2Disp) {
  calendarId = PILAR_2_ID;
} else if (p3Disp) {
  calendarId = PILAR_3_ID;
}

if (!calendarId) {
  return [{
    json: {
      error: `No hay calendarios disponibles para ${solicitudFecha} ${solicitudInicio}-${solicitudFin}`,
      debug: {
        solicitud,
        p1Disp,
        p2Disp,
        p3Disp
      }
    }
  }];
}

// ✅ Reconstruir fecha final limpia (se agenda 15 minutos después del horario recibido, manteniendo la duración original)
const fechaInicio = `${solicitudFecha}T${inicioReal}:00`;
const fechaFinal = `${solicitudFecha}T${finReal}:00`;

// ✅ Resultado final
return [{
  json: {
    ...solicitud,
    Fecha: fechaInicio,
    Fin: fechaFinal,
    Calendar: calendarId
  }
}];

